import loggingfrom pathlib import PathLOG_DIR = Path(__file__).resolve().parent.parent / "logs"LOG_DIR.mkdir(exist_ok=True)file_handler = logging.FileHandler(LOG_DIR / "masks.log")logger = logging.getLogger("masks")logger.setLevel(logging.DEBUG)file_formatter = logging.Formatter(    "%(asctime)s - %(name)s - %(levelname)s - %(message)s")file_handler.setFormatter(file_formatter)logger.addHandler(file_handler)def get_mask_card_number(card_number_full=""):    """функция маскирования номера карты"""    logger.info(        f'Вызов функции get_mask_card_number с аргументом: "{card_number_full}"'    )    if not card_number_full:  # Проверка на пустую строку        logger.error("Аргумент не передан: получена пустая строка")        raise ValueError("Аргумент не передан")    card_number = card_number_full.replace(" ", "")    if card_number.isdigit() and len(card_number) == 16:        num_1 = card_number[0:4]        num_2 = card_number[4:6] + "**"        num_3 = "****"        num_4 = card_number[12:16]        mask_card_number = " ".join([num_1, num_2, num_3, num_4])        logger.info(f"Успешное маскирование карты. Результат: {mask_card_number}")        return mask_card_number    elif len(card_number) < 16:        logger.error(            f"Ошибка: номер карты введен не полностью (получено {len(card_number)} цифр)"        )        raise ValueError("Номер карты введен не полностью")    elif len(card_number) > 16:        logger.error(            f"Ошибка: превышена длина номера карты (получено {len(card_number)} цифр)"        )        raise ValueError("Ошибка! Максимум 16 цифр. Попробуйте снова")    else:        logger.error("Ошибка: номер карты должен состоять только из цифр")        raise ValueError("Ошибка! Номер карты должен состоять из цифр")def get_mask_account(account_number_full=""):    """функция маскирования номера счета"""    logger.info(f'Вызов функции get_mask_account с аргументом: "{account_number_full}"')    if not account_number_full:  # Проверка на пустую строку        logger.error("Аргумент не передан: получена пустая строка")        raise ValueError("Аргумент не передан")    account_number = account_number_full.replace(" ", "")    if account_number.isdigit() and len(account_number) == 20:        mask_account = "**" + account_number[-4:]        logger.info(f"Успешное маскирование счета. Результат: {mask_account}")        return mask_account    elif len(account_number) < 20:        logger.error(            f"Ошибка: номер счета введен не полностью (получено {len(account_number)} цифр)"        )        raise ValueError("Номер счета введен не полностью")    elif len(account_number) > 20:        logger.error(            f"Ошибка: превышена длина номера счета (получено {len(account_number)} цифр)"        )        raise ValueError("Ошибка! Максимум 20 цифр. Попробуйте снова")    else:        logger.error("Ошибка: номер счета должен состоять только из цифр")        raise ValueError("Ошибка! Номер счета должен состоять из цифр")